      var desc = b.description ? '<p class="d">' + F.highlight(b.description, hiTerms) + '</p>' : '';
      var chk = '<input type="checkbox" class="selbox" data-sel="' + b.id + '"' + (st.selected[b.id] ? ' checked' : '') + ' aria-label="Select">';
