          : 'Could not save your changes.';
      }
      return;
    }
    st.editingId = null; st.confirmingDeleteId = null;
    await reload(); render(); showNotice('Saved your changes.');
  }

  async function deleteEntry(id) {
    var r = await api('DELETE', '/api/bookmarks/' + id);
