  // ---- save (preview -> review -> create) ----
  function closeReview() { st.pendingPreview = null; reviewEl.hidden = true; reviewEl.innerHTML = ''; }
  function goToExisting(bk) {
    clearSelection();
    st.activeTags = []; st.query = ''; searchInput.value = ''; searchClear.hidden = true;
